BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats18-q01', '実験計画法',
   '新しいクッキーのレシピを改良したい。材料の配合や焼き時間の候補を、手当たり次第に何百通りも試すのではなく、少ない実験回数でどの条件が結果を左右するかを効率よく突き止めるにはどう実験を組めばよいか——これを考える統計の分野を何と呼ぶ？',
   NULL::text,
   '["実験計画法（少ない実験回数で多くの情報が得られるよう、実験の組み合わせを設計する考え方）", "記述統計（すでに集めたデータの特徴を、平均や分散などの数字でまとめて詳しく説明する分野）", "標本調査（母集団の一部を無作為に抽出して、全体の様子を推測して確かめる方法）", "仮説検定（得られたデータをもとに、母集団についての仮説が正しそうかどうかを判断する手続き）"]',
   0, '[0]', 'single',
   '{"asked": "手当たり次第に実験するのではなく、少ない回数で多くの情報を得るための実験の組み方を考える分野の名前。", "point": "実験計画法は『何を試すか』の前に『どう組み合わせて試すか』を設計することで、実験の回数を減らしながら得られる情報を減らさない考え方。", "kid": "実験計画法は、闇雲にたくさん試す代わりに『この組み合わせで試せば、少ない回数でも欲しい情報がちゃんとそろう』という試し方をあらかじめ考えておくこと。", "eg": "料理のレシピ改良で例えると、砂糖の量・焼き時間・オーブンの温度をそれぞれ3パターンずつ変えたら組み合わせは27通り。全部焼いて食べ比べるのは大変だけど、組み合わせをうまく選べば、もっと少ない回数の実験でも『どの材料が味を左右しているか』はちゃんと分かる。そのうまい選び方を考えるのが実験計画法。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じだけ分かるのに、試す回数はこんなに違う</text><text x=\"90\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">やみくもに全部試す</text><rect x=\"55\" y=\"40\" width=\"70\" height=\"72\" fill=\"#c9a04a\" opacity=\"0.75\"/><text x=\"90\" y=\"82\" fill=\"#141720\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">27通り</text><text x=\"255\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">計画して試す</text><rect x=\"220\" y=\"88\" width=\"70\" height=\"24\" fill=\"#3b82f6\"/><text x=\"255\" y=\"105\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">9通り</text><line x1=\"30\" y1=\"112\" x2=\"310\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">実験計画法＝組み合わせ方を工夫して回数を減らす</text></svg>", "terms": [["実験計画法", "少ない実験回数で多くの情報を得るために、実験の組み合わせをあらかじめ設計する考え方"], ["やみくもな実験", "思いつく限りの組み合わせを手当たり次第に全部試すやり方。回数が組み合わせの数だけ膨れ上がる"]], "think": "なぜ回数を減らしても情報は減らないのかがカギ。闇雲に試すやり方は、確かめたい組み合わせを一つずつ順番に潰していくので、条件が増えるほど試す回数が掛け算式に膨れ上がる。実験計画法は、複数の条件の効果を1回の実験結果からまとめて読み取れるように、組み合わせ方そのものを工夫する。1回の実験に複数の問いへの答えを詰め込めるので、少ない回数でも欲しい情報を取りこぼさずに済む。", "vs": "記述統計は『集めたデータをまとめる』段階、仮説検定は『集めたデータから判断する』段階の話。実験計画法はその前の『どうデータを集めるか(実験をどう組むか)』の段階を扱う点で対象が違う。", "why_asked": "この先に出てくる要因・水準・直交表・乱塊法は、すべて『実験計画法』という1つの目的――少ない実験回数で多くの情報を得る――のための道具立て。まずこの分野が何を目指しているのかを押さえておかないと、個々の道具がバラバラの暗記になる。", "usecase": "新製品の配合を決める食品メーカー、栽培条件を決める農業試験、薬の効き目を確かめる臨床試験、ウェブサイトのボタンの色や文言を決めるA/Bテストなど、条件を変えて何かを試したい場面全般で使われる。", "opt": ["正解。少ない実験回数でより多くの情報が得られるように、実験の条件や組み合わせをあらかじめ設計するのが実験計画法。", "記述統計は、すでに集まったデータの特徴を平均や分散などでまとめる分野。実験をどう組むかを考える実験計画法とは段階が違う。", "標本調査は、母集団の一部を無作為に抽出して全体を推測する方法。実験の条件をどう組み合わせるかを考える実験計画法とは目的が異なる。", "仮説検定は、得られたデータから母集団についての仮説を判断する手続き。データを集めたあとの判断の話で、実験の組み方を設計する話ではない。"]}'),

  ('stats18-q02', '実験計画法',
   'パン屋がクッキーの焼き加減を実験計画で調べる。『砂糖の量(多い/少ない)』や『焼き時間(10分/15分/20分)』のように、結果に影響しそうで実験のために変える条件を『要因』と呼ぶ。では『焼き時間の10分・15分・20分』のような、要因の具体的な値のことは何と呼ぶ？',
   NULL::text,
   '["水準（要因が実際にとる、具体的な値や種類のこと）", "要因（結果に影響しそうで、実験のために意図的に変える条件そのもののこと）", "標本（母集団から取り出して、実際に調べる一部のデータのこと）", "処理群（実験で何らかの処置を受ける、比較のためのグループのこと）"]',
   0, '[0]', 'single',
   '{"asked": "実験計画法で、要因の具体的な値・種類を指す言葉。", "point": "要因は『何を変えるか』という条件の名前、水準はその条件が実際にとる値。焼き時間という要因に対して、10分・15分・20分が水準にあたる。", "kid": "要因は『変える条件そのものの名前』、水準は『その条件が実際に何段階あって、それぞれ何の値か』。焼き時間という要因の中に、10分・15分・20分というそれぞれの水準がある。", "eg": "洋服のサイズで例えると、『サイズ』という項目名が要因、その中のS・M・Lという具体的な選択肢が水準にあたる。『サイズという要因には、S・M・Lという3つの水準がある』というふうに対応する。", "viz": "<svg viewBox=\"0 0 340 122\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">要因＝条件の名前　水準＝条件の具体的な値</text><text x=\"20\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">要因</text><text x=\"120\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">水準</text><line x1=\"20\" y1=\"40\" x2=\"320\" y2=\"40\" stroke=\"#2a2f3f\"/><text x=\"20\" y=\"58\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"start\" font-weight=\"600\">砂糖の量</text><text x=\"120\" y=\"58\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"start\">多い ／ 少ない</text><line x1=\"20\" y1=\"68\" x2=\"320\" y2=\"68\" stroke=\"#2a2f3f\" stroke-dasharray=\"2 2\"/><text x=\"20\" y=\"86\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"start\" font-weight=\"600\">焼き時間</text><text x=\"120\" y=\"86\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"start\">10分 ／ 15分 ／ 20分</text><line x1=\"20\" y1=\"96\" x2=\"320\" y2=\"96\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"114\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">1つの要因の中に、複数の水準がある</text></svg>", "terms": [["要因", "結果に影響しそうで、実験のために意図的に変える条件"], ["水準", "要因が実際にとる、具体的な値や種類"]], "think": "なぜ要因と水準を分けて考える必要があるのかがカギ。『焼き時間を変える』とだけ言っても、それが2段階なのか3段階なのか、具体的に何分と何分を比べるのかが決まらないと実験を組み立てられない。要因は『何を変えるか』という大きな枠、水準は『その枠の中で実際に何を試すか』という中身。この2つを分けて決めることで、『砂糖の量2水準×焼き時間3水準』のように、実験の組み合わせの数を具体的に数えられるようになる。", "vs": "『要因』と『水準』は似た言葉に聞こえるが、要因は条件の種類(何を変えるか)、水準はその条件の中身(どんな値を試すか)という上下の関係にある。水準を聞かれて要因を答えたり、その逆をしたりしないよう注意する。", "why_asked": "この先の一元配置実験・二元配置実験・直交表は、すべて『いくつの要因を、それぞれ何水準ずつ組み合わせるか』という数え方の上に成り立つ。要因と水準の区別があいまいだと、この先の話がすべて曖昧になる。", "usecase": "ウェブサイトのA/Bテストでボタンの色を『要因』、その中の赤・青・緑を『水準』と呼ぶように、実験を設計するときはまず要因と水準を書き出して整理する。", "opt": ["正解。水準は要因が実際にとる具体的な値や種類。焼き時間という要因に対して、10分・15分・20分が水準にあたる。", "要因は結果に影響しそうで実験のために変える条件そのもの(焼き時間・砂糖の量など)の名前。10分・15分・20分のような具体的な値は水準と呼ぶ。", "標本は母集団から取り出して実際に調べる一部のデータのことで、実験の条件を整理する要因や水準とは別の場面で使う言葉。", "処理群は実験で何らかの処置(新しい薬など)を受けるグループのことで、条件の具体的な値である水準とは指しているものが違う。"]}'),

  ('stats18-q03', '実験計画法',
   '肥料の種類(A・B・C)という要因1つだけを変えて、野菜の重さを比べる実験を組んだ。要因が1つだけのこのような実験計画は『一元配置実験』と呼ばれる。その結果を分析するには、既に学んだどの手法が対応するか？',
   NULL::text,
   '["一元配置分散分析（1つの要因の水準どうしで、平均に差があるか比べる、既習のANOVA）", "二元配置分散分析（2つの要因を同時に扱い、水準の組み合わせの効果まで一度に調べる手法）", "回帰分析（ある変数の値から、別の変数の値を予測する式や直線を求める既習の手法）", "カイ二乗検定（人数や個数のような度数の偏りに差があるかどうかを調べる既習の手法）"]',
   0, '[0]', 'single',
   '{"asked": "要因が1つだけの実験計画に対応する、既習の分析手法の名前。", "point": "要因が1つの実験計画(一元配置実験)には、水準どうしの平均を比べる一元配置分散分析(既習のANOVA)が対応する。", "kid": "実験の組み方の話と、その結果を分析する手法の話はいつもセットになっている。要因が1つだけの実験(一元配置実験)には、要因が1つのときの分析手法である一元配置分散分析がぴったり対応する。", "eg": "肥料A・B・Cで野菜の重さを比べた実験は、以前学んだ分散分析の例そのもの。あのとき『群』と呼んでいたA・B・Cは、実験計画法の言葉で言えば『要因(肥料の種類)の3つの水準』にあたる。呼び方が増えただけで、中身は同じ比較。", "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">呼び方が増えても、中身は同じ比較</text><text x=\"90\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">これまで学んだ言い方</text><rect x=\"30\" y=\"42\" width=\"120\" height=\"30\" fill=\"#2a2f3f\"/><text x=\"90\" y=\"58\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">群A・群B・群C</text><text x=\"90\" y=\"68\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">→ 分散分析</text><text x=\"250\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">実験計画法の言い方</text><rect x=\"190\" y=\"42\" width=\"120\" height=\"30\" fill=\"#3b82f6\"/><text x=\"250\" y=\"58\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">要因(肥料)の3水準</text><text x=\"250\" y=\"68\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">→ 一元配置実験</text><line x1=\"150\" y1=\"57\" x2=\"190\" y2=\"57\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"190,57 183,53 183,61\" fill=\"#60a5fa\"/><text x=\"170\" y=\"98\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">要因が1つ＝一元配置実験</text><text x=\"170\" y=\"114\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">分析は一元配置分散分析(既習のANOVA)</text></svg>", "terms": [["一元配置実験", "要因が1つだけの実験計画"], ["一元配置分散分析(一元配置ANOVA)", "1つの要因の水準どうしで平均に差があるかを調べる、既に学んだ分散分析"]], "think": "なぜ『一元配置実験』という新しい呼び方がいるのかがカギ。以前学んだ分散分析は『3つの群を比べる』という分析の手続きの名前だった。実験計画法では、その前段階である『そもそも実験をどう組むか』にも名前をつける。要因が1つだけの実験の組み方を一元配置実験と呼び、その結果を分析する一元配置分散分析とペアにすることで、『実験の組み方』と『分析の仕方』を対応づけて考えられるようになる。これから先、要因が2つ、3つと増えていく実験計画にも、それぞれ対応する分析手法が出てくる。", "vs": "『一元配置実験』は実験の組み方(要因が1つ)を指す言葉、『一元配置分散分析』はその結果の分析手法を指す言葉。呼び分けているだけで、対象にしている場面(要因1つの比較)は同じ。", "why_asked": "次に出てくる二元配置実験・二元配置分散分析を理解するための土台。まず要因が1つの場合の対応関係を押さえておかないと、要因が2つになったときの対応が飲み込みにくい。", "usecase": "比べたい条件が1種類だけ(肥料の種類だけ、教材の種類だけ)のときの実験の組み方と分析の型として使う。", "opt": ["正解。要因が1つだけの一元配置実験には、水準どうしの平均を比べる一元配置分散分析(既に学んだANOVA)が対応する。", "二元配置分散分析は要因が2つあるときに使う手法。今回は肥料の種類という要因1つだけなので、二元配置分散分析はまだ出番がない。", "回帰分析はある変数から別の変数の値を予測する手法で、水準どうしの平均を比べる今回の目的とは異なる。", "カイ二乗検定は人数や個数のような度数の偏りを調べる手法で、野菜の重さという数値の平均を比べる今回の目的とは異なる。"]}'),

  ('stats18-q04', '実験計画法',
   'パン屋が、発酵時間(短い/長い)と焼成温度(低い/高い)がパンのふくらみに与える影響を調べたい。発酵時間だけを変える実験と、焼成温度だけを変える実験を別々に行う代わりに、2つの要因を組み合わせて同時に変える二元配置実験を組む一番の理由は？',
   NULL::text,
   '["発酵時間と焼成温度を別々に変えただけでは見えない、組み合わせの交互作用まで調べられるから", "焼成温度の影響を受けずに、発酵時間の効果だけをより高い精度で測定できるようになるから", "発酵時間と焼成温度、それぞれの水準の数をあとから自由に増やしたり減らしたりできるから", "発酵時間の実験と焼成温度の実験を、同じオーブンを使って同時に済ませられて手間が省けるから"]',
   0, '[0]', 'single',
   '{"asked": "1つずつ変える実験ではなく、2つの要因を組み合わせて同時に変える二元配置実験を組む一番の理由。", "point": "要因を1つずつ別々に変える実験では、『組み合わせたときだけ生じる変化(交互作用)』が最初から見えない。二元配置実験なら、それも同時に調べられる。", "kid": "発酵時間だけの実験と焼成温度だけの実験を別々にやっても、『発酵時間が長いときに限って、高温がよく効く』というような、組み合わせならではの変化は分からないまま。2つを同時に変える実験なら、それも一緒に確かめられる。", "eg": "以前、肥料の種類と水やりの頻度を同時に変える分散分析で『交互作用』を学んだ。あのときの発想と同じで、パンでも発酵時間と焼成温度を別々にではなく同時に振ってみないと、『組み合わせて初めて起きる変化』は見つけようがない。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">別々に変えるだけでは、組み合わせの効果が見えない</text><text x=\"85\" y=\"34\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">発酵時間だけ変える実験</text><text x=\"255\" y=\"34\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">焼成温度だけ変える実験</text><rect x=\"30\" y=\"42\" width=\"110\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"85\" y=\"56\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">短い→長いでの変化</text><rect x=\"200\" y=\"42\" width=\"110\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"255\" y=\"56\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">低い→高いでの変化</text><text x=\"170\" y=\"80\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">組み合わせたときだけ起きる変化は、別々には分からない</text><rect x=\"70\" y=\"92\" width=\"200\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"170\" y=\"109\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">発酵時間×焼成温度を同時に変える</text><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">＝二元配置実験なら交互作用も分かる</text></svg>", "terms": [["二元配置実験", "2つの要因を同時に変えて、その効果と組み合わせの効果をあわせて調べる実験計画"], ["交互作用効果", "2つの要因を組み合わせると、単独の効果の足し算では説明できない変化が生じること。既習のANOVAの発展分と同じ現象"]], "think": "なぜ別々に変える実験では交互作用が見えないのかがカギ。発酵時間だけを変える実験は、焼成温度をずっと同じ値に固定したまま行う。だから『焼成温度を変えたら発酵時間の効き方まで変わる』かどうかは、その実験のデータには一切現れない。焼成温度だけを変える実験も同じで、発酵時間を変えたときの影響は最初から実験の外に置かれている。2つの要因を同時に振る二元配置実験なら、発酵時間の効果・焼成温度の効果に加えて、両方を組み合わせたときだけ生じる交互作用効果まで、同じ1つの実験データから読み取れる。", "vs": "『発酵時間の効果だけをより正確に測る』という目的なら、焼成温度を固定した一元配置実験でも一応は測れる。しかし『組み合わせでどう変わるか』まで知りたいなら、一元配置実験を2回繰り返しても答えは出ない。目的が違えば必要な実験の組み方も違う。", "why_asked": "実験計画法では、要因を1つずつ確かめれば十分だと思い込みやすい。しかし現実には『組み合わせて初めて効く条件』が珍しくない。二元配置実験がなぜ必要かを理解していないと、大事な組み合わせの効果を見落としたまま実験を終えてしまう。", "usecase": "パンの発酵時間×焼成温度、広告の掲載場所×キャッチコピーなど、2つ以上の条件を同時に工夫したい場面で、組み合わせの効果まで含めて確かめたいときに使う。", "opt": ["正解。発酵時間と焼成温度を別々に変えるだけでは、組み合わせによる交互作用効果が最初から実験の外に置かれてしまう。同時に変えればそれも調べられる。", "焼成温度を固定して発酵時間だけを変える一元配置実験でも、発酵時間単独の効果はある程度測れる。二元配置実験の一番の利点は、それに加えて交互作用まで調べられる点にある。", "二元配置実験を組んでも、あらかじめ決めた水準の数(短い/長いなど)がそのまま。水準の数を自由に増減できるようにする仕組みではない。", "同じオーブンを使う・使わないは実験の手間の話であり、二元配置実験を組む一番の理由(交互作用まで調べられること)とは関係がない。"]}'),

  ('stats18-q05', '実験計画法',
   '3種類の肥料(A・B・C)の効果を畑で比べたい。畑は場所によって日当たりや土の質が少しずつ違い、そのままでは肥料以外の差が結果に混ざってしまう。そこで畑を似た条件どうしの区画(ブロック)に分け、各区画の中でA・B・Cすべてを試すことで、場所による余計な影響を抑える方法を何と呼ぶ？',
   NULL::text,
   '["乱塊法（実験条件以外の余計な要因をブロックに分けてそろえ、影響を抑える計画）", "無作為抽出（母集団から標本を、偏りなくランダムに選び出す既に学んだ方法）", "多重比較（分散分析で有意差が出たあと、どの群が違うかを個別に比べる既習の手続き）", "層別抽出（母集団をいくつかの層に分けたうえで、各層から標本を抽出する方法）"]',
   0, '[0]', 'single',
   '{"asked": "余計な要因の影響を抑えるために、似た条件どうしでグループ分けして実験する方法の名前。", "point": "乱塊法は、実験条件以外の余計な差(天候・場所・担当者など)をブロックでそろえ、ブロックの中でだけ水準を比べることでその影響を抑える。", "kid": "畑によって日当たりや土の質が違うと、肥料の効き目なのか場所の違いなのか分からなくなる。そこで似た条件の場所どうしを1つのグループ(ブロック)にまとめ、そのグループの中でA・B・Cを全部試せば、場所の違いの影響を抑えたまま肥料だけの効果を比べられる。", "eg": "クラス対抗の徒競走で例えると、走力がバラバラな子をそのまま横一列に並べて競わせると、走力の差が結果を左右してしまう。走力が近い子どうしを同じ組にして走らせれば、組の中の差はより純粋に『その日の調子』などに近づく。ブロックは、この『似た者どうしを同じ組にする』工夫。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">似た条件どうしをブロックにまとめる</text><text x=\"24\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">日当たり良い区画</text><rect x=\"20\" y=\"38\" width=\"90\" height=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"35\" y=\"55\" fill=\"#e8eaf0\" font-size=\"8\">A B C</text><text x=\"130\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">日当たり中の区画</text><rect x=\"126\" y=\"38\" width=\"90\" height=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"141\" y=\"55\" fill=\"#e8eaf0\" font-size=\"8\">A B C</text><text x=\"236\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">日当たり悪い区画</text><rect x=\"232\" y=\"38\" width=\"88\" height=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"247\" y=\"55\" fill=\"#e8eaf0\" font-size=\"8\">A B C</text><text x=\"170\" y=\"82\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">各ブロックの中で必ずA・B・C全部を試す</text><text x=\"170\" y=\"100\" fill=\"#6ab08d\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">日当たりの差はどのブロックにも公平に含まれる</text><text x=\"170\" y=\"118\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">これが乱塊法</text></svg>", "terms": [["乱塊法", "実験条件以外の余計な要因をブロックに分けてそろえ、その影響を抑える実験計画"], ["ブロック(ブロック因子)", "似た条件どうしをまとめた、比較のための区画やグループ"]], "think": "なぜブロックに分けるだけで余計な影響を抑えられるのかがカギ。もしブロックに分けず畑全体にバラバラにA・B・Cを配置すると、たまたま日当たりの良い場所にAが多く割り当てられ、Aの結果が実際以上に良く見えてしまうかもしれない。ブロックに分けて、各ブロックの中で必ずA・B・Cを1つずつ試せば、日当たりの良し悪しはどのブロックにも公平に含まれることになる。肥料の違いによる差と、場所の違いによる差を、ブロックという単位で切り分けて考えられるようになる。", "vs": "無作為抽出は母集団から標本を選ぶときの話、乱塊法は実験の中でグループ分けをする話で、場面が違う。名前が似ている層別抽出(母集団をいくつかの層に分けて標本を取る)とは、『グループに分ける』発想は共通しているが、抽出のための分け方(層別抽出)か、余計な影響を抑えるための分け方(乱塊法)かという目的が異なる。", "why_asked": "実験計画法では、比べたい要因(肥料の種類)以外にも、結果に影響しそうな余計な要因(天候・場所・担当者)が必ず存在する。それを無視すると、この後学ぶ『交絡』(効果が混ざって分からなくなる)が起きる。乱塊法は、その交絡を防ぐための具体的な工夫の1つ。", "usecase": "農業試験で畑の場所ごとの違いを抑える、工場の実験で機械や担当者ごとの違いを抑える、臨床試験で施設ごとの違いを抑えるなど、比べたい条件以外の差が結果に混ざりそうな場面で使う。", "opt": ["正解。似た条件どうしをブロックにまとめ、各ブロックの中で全部の水準を試すことで、実験条件以外の余計な影響を抑えるのが乱塊法。", "無作為抽出は母集団から標本を偏りなく選び出す方法で、実験の中で条件をブロックに分ける乱塊法とは目的も場面も異なる。", "多重比較は分散分析で有意差が出たあとに、具体的にどの群が違うかを個別に比べ直す手続きで、実験を組む段階の乱塊法とは別の話。", "層別抽出は母集団をいくつかの層に分けて標本を取る方法で、実験の余計な影響を抑えるためにブロックへ分ける乱塊法とは目的が異なる。"]}'),

  ('stats18-q06', '実験計画法',
   '肥料の種類(3水準)・水やりの頻度(3水準)・日当たり(3水準)という3つの要因を全部の組み合わせで試すと3×3×3=27通りになる。『直交表』という特別な表を使うと、27通りより少ない回数の実験で3つの要因それぞれの効果を効率よく見積もれる。この直交表とはどのようなものか？',
   NULL::text,
   '["複数の要因の水準を、全部を試さなくても効果を見積もれるよう工夫して並べた表", "実験で得られたデータを、平均・分散・標準偏差などの数字にまとめて記録するための表", "母集団から無作為に選んだ標本を、抽出した順番のとおりに並べて記録した一覧表", "2つの変数の値をそれぞれ縦と横の軸にとり、交わる位置に点を打って関係を見るための表"]',
   0, '[0]', 'single',
   '{"asked": "複数の要因を効率よく組み合わせて実験するための、特別な組み合わせ表の名前。", "point": "直交表は、要因の組み合わせを全部試さなくても各要因の効果をそれぞれ分離して見積もれるように、あらかじめ工夫して並べられた表。", "kid": "直交表は、実験する組み合わせをあらかじめ選んでおいてくれる『効率の良い時間割』のようなもの。この時間割どおりに実験すれば、全部の組み合わせを試さなくても、それぞれの要因がどれくらい効いているかが分かる。", "eg": "テストの範囲がとても広いとき、教科書の全ページを1文字残らず読み直す代わりに、よく出るところを効率よく組み合わせた『まとめノート』で勉強するようなもの。直交表は、実験の『まとめノート』にあたる、効率の良い組み合わせの選び方。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">27通り全部ではなく、選び抜いた9通りで試す</text><text x=\"90\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">全要因配置(27通り)</text><g fill=\"#2a2f3f\"><rect x=\"35\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"50\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"65\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"80\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"95\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"110\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"125\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"35\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"50\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"65\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"80\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"95\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"110\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"125\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"35\" y=\"68\" width=\"12\" height=\"12\"/><rect x=\"50\" y=\"68\" width=\"12\" height=\"12\"/><rect x=\"65\" y=\"68\" width=\"12\" height=\"12\"/><rect x=\"80\" y=\"68\" width=\"12\" height=\"12\"/></g><text x=\"90\" y=\"98\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">27マスすべて試す</text><text x=\"255\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">直交表(9通り)</text><g fill=\"#3b82f6\"><rect x=\"205\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"235\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"265\" y=\"38\" width=\"12\" height=\"12\"/><rect x=\"220\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"250\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"280\" y=\"53\" width=\"12\" height=\"12\"/><rect x=\"235\" y=\"68\" width=\"12\" height=\"12\"/><rect x=\"265\" y=\"68\" width=\"12\" height=\"12\"/><rect x=\"205\" y=\"68\" width=\"12\" height=\"12\"/></g><text x=\"255\" y=\"98\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">9マスだけ選ぶ</text><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">少ない回数でも、偏りなく各要因の効果を見積もれる</text></svg>", "terms": [["直交表", "複数の要因の組み合わせを、全部試さなくても各要因の効果を分離して見積もれるように工夫して並べた表"], ["全要因配置(フル配置)", "考えられる組み合わせを漏れなく全部試す実験の組み方。要因が増えると回数が急激に膨らむ"]], "think": "なぜ全部の組み合わせを試さなくても各要因の効果が見積もれるのかがカギ。直交表は、それぞれの要因の水準が表全体の中で偏りなく同じ回数ずつ登場するように、あらかじめ組み合わせが選ばれている。この『偏りのなさ』のおかげで、ある要因の水準を変えたときの結果の変化を、他の要因の影響が互いに打ち消し合った状態で取り出せる。だから27通り全部を試さなくても、9通りのような少ない回数で、3つの要因それぞれの効果を見積もれる。", "vs": "全部の組み合わせを試す『全要因配置』と違い、直交表を使う実験は組み合わせの数を減らしている。減らした分だけ交互作用まで細かくは調べにくくなるトレードオフはあるが、主に知りたい各要因の効果(主効果)を見積もるには十分な情報が得られるように設計されている。", "why_asked": "要因が増えるほど全部の組み合わせを試す実験は非現実的な回数になる(要因が5つで水準3ずつなら3の5乗=243通り)。直交表は、この『組み合わせ爆発』を回避しながら実験計画法の目的(少ない回数で多くの情報を得る)を実現する、代表的な道具。", "usecase": "工場の製品の品質を左右する複数の条件(温度・圧力・材料の種類など)を同時に最適化したいとき、品質工学の現場で広く使われる。", "opt": ["正解。直交表は、要因の組み合わせを全部試さなくても、各要因の効果を分離して見積もれるように組み合わせ方を工夫して並べた表。", "実験結果を平均・分散・標準偏差などにまとめる表は、実験のあとの分析結果をまとめる表であり、実験する組み合わせを選ぶための直交表とは役割が違う。", "標本を抽出した順番どおりに並べた一覧表は無作為抽出の記録であり、要因の組み合わせを効率よく選ぶための直交表とは目的が異なる。", "2つの変数を縦横の軸にとって関係を見る表は散布図の説明であり、複数の要因の組み合わせを選ぶための直交表とは別のものを指している。"]}'),

  ('stats18-q07', '実験計画法',
   '3つの要因(それぞれ3水準)を全部の組み合わせで試すと27通りだが、直交表を使うと9通りの実験で済ませられる。実験回数を27通りから9通りに減らしても、それぞれの要因の効果をちゃんと見積もれるのはなぜ？',
   NULL::text,
   '["直交表の組み合わせは、それぞれの要因の水準が表全体で偏りなく登場するように選ばれているから", "直交表を使うと、3つの要因のうち一番効きそうな1つだけを残し、残り2つの要因を無視するから", "直交表を使うと、水準の数そのものが3水準から自動的に減らされるから", "実験回数を減らした分を、測定機器の精度を上げることで埋め合わせているから"]',
   0, '[0]', 'single',
   '{"asked": "組み合わせの数を減らしても、各要因の効果を見積もれる直交表の仕組み。", "point": "直交表は、水準の登場回数を表全体で均等にそろえることで、他の要因の影響を打ち消しながら、それぞれの要因の効果だけを取り出せるようにしている。", "kid": "直交表を使った実験回数の減らし方は、要因を無視したり水準を減らしたりしているわけではない。組み合わせの選び方そのものを工夫して、少ない回数でも各要因の効果がちゃんと見える形にしている。", "eg": "クラス全員に3段階の甘さのドリンクを試してもらう感想アンケートで例えると、全員に全部の組み合わせを飲んでもらわなくても、『甘さの低い・中・高がそれぞれ同じ人数ずつ体験するように』うまく割り振ってアンケートを配れば、少ない回答数でも甘さごとの好みの傾向はちゃんと見える。これが直交表の考え方。", "viz": "<svg viewBox=\"0 0 340 144\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">各要因の水準が、表全体で同じ回数ずつ登場する</text><text x=\"60\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">肥料</text><text x=\"150\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">水やり</text><text x=\"240\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">日当たり</text><g font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\"><text x=\"60\" y=\"48\">A</text><text x=\"150\" y=\"48\">多</text><text x=\"240\" y=\"48\">良</text><text x=\"60\" y=\"62\">A</text><text x=\"150\" y=\"62\">中</text><text x=\"240\" y=\"62\">悪</text><text x=\"60\" y=\"76\">A</text><text x=\"150\" y=\"76\">少</text><text x=\"240\" y=\"76\">中</text><text x=\"60\" y=\"90\">B</text><text x=\"150\" y=\"90\">多</text><text x=\"240\" y=\"90\">中</text><text x=\"60\" y=\"104\">B</text><text x=\"150\" y=\"104\">中</text><text x=\"240\" y=\"104\">良</text></g><rect x=\"30\" y=\"38\" width=\"270\" height=\"72\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"105\" y1=\"38\" x2=\"105\" y2=\"110\" stroke=\"#2a2f3f\"/><line x1=\"195\" y1=\"38\" x2=\"195\" y2=\"110\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"128\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">「肥料A」の行にも水やり・日当たりの各水準が均等に混ざる</text><text x=\"170\" y=\"142\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">→ 他の要因の影響が打ち消し合う</text></svg>", "terms": [["主効果", "ある1つの要因の水準を変えたときに生じる、その要因単独の効果"], ["バランス(均等な配置)", "各要因の水準が、表全体で同じ回数ずつ登場するように組まれていること"]], "think": "なぜ均等に配置するだけで、他の要因の影響を打ち消せるのかがカギ。ある要因(たとえば肥料)の効果だけを知りたいとき、残りの要因(水やり・日当たり)の影響がたまたま偏って混ざっていると、肥料の効果が正しく見えなくなる。直交表では、肥料のどの水準を選んでも、水やりや日当たりの各水準が同じ回数ずつ組み合わさるように配置されている。すると水やりや日当たりの影響は、肥料のどの水準についても平均的に同じだけ混ざることになり、比べたときに互いに打ち消し合う。残るのは肥料の水準による違いだけになるので、少ない回数でも肥料単独の効果を取り出せる。", "vs": "『回数を減らす』というと水準の数を減らしたり要因を無視したりする方法を思い浮かべがちだが、直交表はそのどちらもしない。要因も水準もそのままに、組み合わせの選び方だけを工夫して回数を減らす点が特徴。", "why_asked": "直交表が『何をしている表か』を暗記するだけでなく『なぜ少ない回数で効果を見積もれるのか』という理屈が分かっていないと、直交表を使ってよい場面と使えない場面(交互作用を細かく知りたいときなど)の判断ができなくなる。", "usecase": "品質工学の実験で、確かめたい条件が多いときに、全部の組み合わせを試す時間もコストもない場面で、直交表を使って効率よく各条件の効果を見積もる。", "opt": ["正解。直交表の組み合わせは各要因の水準が表全体で偏りなく登場するように選ばれているので、他の要因の影響が打ち消し合い、少ない回数でも各要因の効果を見積もれる。", "直交表は要因を無視するのではなく、3つの要因すべての効果を見積もるために使う表。一部の要因だけを残して残りを無視するのでは、直交表を使う意味がなくなる。", "直交表を使っても、あらかじめ決めた水準の数(3水準)はそのまま保たれる。水準の数そのものを自動的に減らす仕組みではない。", "実験回数を減らした分を測定機器の精度で埋め合わせる、という仕組みではない。回数を減らしても情報を保てるのは、組み合わせの選び方の工夫による。"]}'),

  ('stats18-q08', '実験計画法',
   '新しい肥料の効果を調べる実験で、新しい肥料はすべて日当たりの良い区画に、これまでの肥料はすべて日当たりの悪い区画に植えてしまった。この状態で新しい肥料の区画のほうが野菜がよく育っても、その理由をはっきりとは言えない。この『肥料の効果』と『日当たりの効果』が混ざってしまっている状態を何と呼ぶ？',
   NULL::text,
   '["交絡（比べたい要因の効果と、余計な要因の効果が混ざり合って、切り分けられなくなること）", "交互作用（2つの要因を組み合わせると、単独の効果の足し算では説明できない変化が生じること）", "疑似相関（別の要因が両方に影響しているせいで、直接は関係のない2つのことが関係あるように見えること）", "選択バイアス（比べる対象の選ばれ方が偏っていて、結果が本来の姿からずれること）"]',
   0, '[0]', 'single',
   '{"asked": "実験計画がずさんだと、比べたい要因の効果と余計な要因の効果が混ざってしまうことを指す言葉。", "point": "肥料の割り当てと日当たりの良し悪しが完全に重なってしまうと、どちらの影響で育ちが良くなったのか、実験結果からはもう切り分けられない。これが交絡。", "kid": "新しい肥料の区画がぜんぶ日当たりの良い場所だと、育ちが良くなったのが『肥料のおかげ』なのか『日当たりのおかげ』なのか、あとからでは区別できなくなる。2つの原因候補が、いつも同じ区画にセットでくっついてしまっているから。", "eg": "以前、気温が上がるとアイスの売上も水難事故も増えるという疑似相関を学んだ。あのときは『気温』という余計な要因が両方に影響していた。今回も『日当たり』という余計な要因が、肥料の割り当てと野菜の育ちの両方に重なってしまっている。あのときは自然に集まったデータの話だったが、今回は実験の組み方がずさんだったせいで、自分から交絡を作ってしまっている点が違う。", "viz": "<svg viewBox=\"0 0 340 142\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">2つの原因候補が、いつも同じ区画にセット</text><rect x=\"30\" y=\"30\" width=\"130\" height=\"44\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"95\" y=\"48\" fill=\"#141720\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">新しい肥料</text><text x=\"95\" y=\"62\" fill=\"#141720\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">日当たり良い</text><rect x=\"180\" y=\"30\" width=\"130\" height=\"44\" fill=\"#2a2f3f\"/><text x=\"245\" y=\"48\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">これまでの肥料</text><text x=\"245\" y=\"62\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">日当たり悪い</text><text x=\"170\" y=\"94\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">育ちが良いのは肥料？日当たり？→区別できない</text><text x=\"170\" y=\"112\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">これが交絡</text><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">乱塊法で日当たりをどちらの肥料にも均等に混ぜれば防げる</text></svg>", "terms": [["交絡", "比べたい要因の効果と、余計な要因の効果が混ざり合って切り分けられなくなること"], ["交絡因子", "比べたい要因と同時に結果にも影響してしまう、余計な要因(ここでは日当たり)"]], "think": "なぜ乱塊法が交絡を防ぐ工夫になるのかがカギ。今回の実験は、新しい肥料の区画と日当たりの良い区画がぴったり重なってしまっている。もし乱塊法のように、日当たりの良し悪しでブロックに分け、各ブロックの中で新旧両方の肥料を試していれば、日当たりの影響はどちらの肥料にも同じように混ざることになり、肥料どうしを比べたときに打ち消し合う。日当たりと肥料の割り当てをあえてバラバラにしておくことが、交絡を防ぐ鍵になる。ずさんな実験計画は、この『バラバラにしておく』手間を省いてしまったために起きる。", "vs": "以前学んだ疑似相関は、気温のような余計な要因が2つの出来事を自然に結びつけて見せる現象だった。交絡は、その『余計な要因が結果を混ぜてしまう』という原因そのものを指す言葉で、疑似相関は交絡が引き起こす見え方の1つ。実験計画法の文脈では、実験の割り振り方がずさんだと自分から交絡を作り出してしまう点が、観察データの疑似相関との違い。", "why_asked": "乱塊法や直交表がなぜ必要なのかは、『放っておくと交絡が起きるから』という理由に行き着く。交絡がどんな状態を指すのかを理解していないと、これらの実験計画の工夫がなぜ効くのかが分からなくなる。", "usecase": "臨床試験で新しい薬を重症患者にばかり、既存の薬を軽症患者にばかり使ってしまうと、薬の効果と重症度の効果が交絡する。実験を組む段階で、比べたい要因と余計な要因が重ならないよう気をつける必要がある。", "opt": ["正解。肥料の割り当てと日当たりの良し悪しが重なってしまい、育ちの良さが肥料のおかげか日当たりのおかげか切り分けられなくなっている。これが交絡。", "交互作用は2つの要因を組み合わせたときに単独の足し算では説明できない変化が生じることで、原因どうしが区別できなくなる今回の状態とは違う話。", "疑似相関は余計な要因が2つの出来事を関係あるように見せる現象そのものの名前。今回のように実験の割り振り方が原因で効果が混ざる状態は、交絡と呼ぶほうが的確。", "選択バイアスは比べる対象の選ばれ方自体が偏っていることを指す言葉で、今回のように要因どうしの効果が混ざってしまう状態とは指しているものが違う。"]}'),

  ('stats18-q09', '実験計画法',
   '同じ条件(同じ肥料・同じ区画の日当たり)で野菜を1株だけ育てて重さを測っても、その1株がたまたま病気がちだったり元気だったりする可能性がある。そこで同じ条件で複数株を育てて重さを測る『反復』を行う一番の役割は？',
   NULL::text,
   '["同じ条件でもばらつく、誤差の大きさを見積もれるようにすること", "実験に使う肥料の種類そのものを、途中から増やせるようにすること", "1株ごとの重さの記録を、あとから修正できるようにすること", "実験にかかる日数を、1株だけのときより大幅に短縮すること"]',
   0, '[0]', 'single',
   '{"asked": "同じ条件で複数回実験する『反復』が果たす一番の役割。", "point": "反復は、同じ条件でもどれくらいばらつくかという誤差の大きさを見積もれるようにする。", "kid": "同じ肥料・同じ場所で育てても、1株ごとに重さは少しずつ違う。この『同じ条件でもどうしても出てしまうばらつき』の大きさを知るために、わざと同じ条件で何株か育てて比べるのが反復。", "eg": "同じ人が同じ体重計に3回続けて乗ると、毎回ぴったり同じ数値にはならず、少しだけ数字がぶれることがある。このぶれの大きさを知っておけば、『別の日に測った体重の差』が本当の体重変化なのか、ただの測定のばらつきなのかを見分けやすくなる。反復は、この『ぶれの大きさ』を実験でも測っておく作業。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ条件でも、株ごとに重さは少しばらつく</text><line x1=\"40\" y1=\"70\" x2=\"300\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><circle cx=\"120\" cy=\"70\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"160\" cy=\"70\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"150\" cy=\"70\" r=\"5\" fill=\"#3b82f6\"/><text x=\"120\" y=\"90\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">210g</text><text x=\"150\" y=\"90\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">225g</text><text x=\"160\" y=\"102\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">218g</text><text x=\"145\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">同じ肥料・同じ区画で育てた3株</text><text x=\"170\" y=\"118\" fill=\"#6ab08d\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">このばらつきの大きさ＝反復で分かる誤差</text><text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">差が誤差より大きいかどうかで、本当の効果か判断できる</text></svg>", "terms": [["反復", "同じ条件で複数回実験を行うこと"], ["誤差(誤差のばらつき)", "同じ条件で実験しても生じてしまう、結果の細かいばらつき"]], "think": "なぜ反復がないと誤差の大きさが分からないのかがカギ。もし各条件を1株ずつしか育てなければ、条件どうしの重さの差が肥料の本当の効果によるものなのか、それともたまたまその株がよく育っただけなのか、区別する手がかりが手元にない。同じ条件で複数株育てて反復すれば、『同じ条件でもこれくらいはばらつく』という基準の大きさが分かる。この基準(誤差のばらつき)と、条件どうしの差の大きさを比べて初めて、その差が本当に肥料による違いと言えるのか、それとも誤差の範囲内なのかを判断できる。以前学んだ分散分析のF値(群間分散÷群内分散)の『群内分散』も、この反復によって測れる誤差のばらつきにあたる。", "vs": "反復(同じ条件で複数回試すこと)と、水準(その要因がとる違う値の数)は別物。水準は要因を何段階に分けて比べるかの話、反復は決めた各条件をそれぞれ何回ずつ試すかの話。", "why_asked": "実験計画は、要因・水準・組み合わせ方(直交表など)を工夫するだけでは完成しない。反復を入れて誤差のばらつきを測る仕組みがないと、そもそも差が意味のある差なのかを判断する物差しが持てない。", "usecase": "工場の実験で同じ設定の機械を複数回稼働させて誤差を見積もる、農業試験で同じ条件の区画を複数箇所用意するなど、結果の差が本物かどうかを判断したい実験全般で行う。", "opt": ["正解。同じ条件で複数回実験することで、条件が同じでもどれくらい結果がばらつくか(誤差の大きさ)を見積もれるようになる。", "反復は同じ条件を複数回試すことで、肥料の種類そのものの数(要因の水準)を増やすかどうかとは別の話。", "反復は結果の記録をあとから修正するための作業ではなく、あらかじめ複数回試して誤差の大きさを見積もるための実験の組み方。", "反復は同じ条件を複数回試すので、むしろ1株だけのときより手間や日数は増える。日数を短縮する工夫ではない。"]}'),

  ('stats18-q10', '実験計画法',
   '実験計画法は、条件を変えて試す実験の組み方を効率化する考え方。次の4つの場面のうち、実験計画法の考え方が当てはまらないのはどれ？',
   NULL::text,
   '["すでに集計済みの去年の売上データを、月ごとの平均と標準偏差にまとめて資料に載せる", "工場で温度・圧力・材料の配合という複数の条件を組み合わせて、不良品が減る条件を探す", "農業試験で肥料の種類や水やりの頻度を変えた区画をいくつも用意して、収穫量を比べる", "ウェブサイトでボタンの色や文言を複数パターン用意し、クリック率が高い組み合わせを探る"]',
   0, '[0]', 'single',
   '{"asked": "実験計画法の考え方(条件を変えて組み合わせを試す)が当てはまらない場面はどれか。", "point": "実験計画法は『これから条件を変えて試す』場面の考え方。すでに集まったデータを集計するだけの作業には出番がない。", "kid": "工場の条件出し・農業試験・ウェブサイトのA/Bテストは、どれも『これから条件をいくつか変えて試してみる』場面。一方、去年の売上データを平均と標準偏差にまとめる作業は、すでに集まったデータをまとめるだけで、これから何かの条件を変えて試すわけではない。", "eg": "実験計画法は『次の実験をどう組むか』という、これから先に向けた設計図。すでに撮り終えた写真をアルバムに整理する作業(記述統計)と、これから撮る写真の構図をあれこれ工夫して決める作業(実験計画法)くらい、向いている方向が違う。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">「これから条件を変えて試す」場面かどうか</text><rect x=\"20\" y=\"28\" width=\"300\" height=\"60\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.3\" rx=\"4\"/><text x=\"170\" y=\"42\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">実験計画法があてはまる</text><text x=\"170\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">工場の条件出し／農業試験／ウェブサイトのA/Bテスト</text><text x=\"170\" y=\"76\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">＝これから要因・水準を変えて試す</text><rect x=\"60\" y=\"98\" width=\"220\" height=\"36\" fill=\"#2a2f3f\"/><text x=\"170\" y=\"114\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">去年の売上データを平均・標準偏差にまとめる</text><text x=\"170\" y=\"127\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">＝すでにあるデータの記述統計。実験計画法の出番ではない</text></svg>", "terms": [["実験計画法", "これから条件を変えて試す実験を、効率よく組むための考え方"], ["記述統計", "すでに集まったデータの特徴を、平均や分散などの数字でまとめる分野。既に学んだ内容"]], "think": "なぜ売上データの集計だけが当てはまらないのかがカギ。工場・農業試験・A/Bテストの3つは、どれも複数の条件(温度や圧力、肥料や水やり、ボタンの色や文言)を実験者が意図的に変えて、どの組み合わせが良い結果を生むかをこれから調べようとしている。一方、去年の売上データをまとめる作業は、すでに起きたことを記録し直すだけで、条件を変えて何かを試してはいない。実験計画法が扱うのは常に『これから条件を変えて試す場面』であり、すでにあるデータをまとめる場面(記述統計)とは向いている方向が逆になる。", "vs": "この講座の最初のほうで学んだ記述統計(平均・標準偏差でデータをまとめる)と、実験計画法はどちらも統計の分野だが役割が違う。記述統計はすでにあるデータの整理、実験計画法はこれから行う実験の設計。", "why_asked": "実験計画法の用語(要因・水準・直交表・乱塊法)を覚えても、『どんな場面でこの考え方を持ち出すべきか』を見誤ると、実務で使いどころを間違える。境界線(これから条件を変えて試すかどうか)をはっきりさせておく。", "usecase": "工場の生産条件の最適化、農業試験の肥料・栽培条件の比較、ウェブサービスのA/Bテストによる改善など、これから条件を変えて何かを試したいときはいつも実験計画法の出番になる。", "opt": ["正解。すでに集計済みのデータをまとめる作業は記述統計の範囲であり、これから条件を変えて試すわけではないので、実験計画法の出番ではない。", "工場で複数の条件を組み合わせて不良品の少ない条件を探す取り組みは、実験計画法がもっとも活躍する代表的な場面の1つ。", "農業試験で肥料や水やりの条件を変えた区画を用意して収穫量を比べる取り組みは、実験計画法の考え方がそのまま当てはまる典型的な場面。", "ウェブサイトのA/Bテストは、複数パターンを用意してどの組み合わせが良い結果を生むかを試す点で、実験計画法の考え方の実務での代表例。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
